insert into public.questions (id, passage_id, topik, pertanyaan, opsi, kunci, pembahasan) values
(md5('neg-q-1')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Seorang penjual menyapa pembeli, lalu pembeli berkata bahwa ia mencari sepatu kerja. Bagian percakapan itu paling tepat dianalisis sebagai…$q$, $q$["Persetujuan karena harga telah disepakati","Penutup karena ada sapaan","Penawaran karena harga telah berubah","Orientasi yang diikuti pengajuan kebutuhan"]$q$::jsonb, 3, $q$Sapaan membuka interaksi, sedangkan kebutuhan sepatu merupakan pengajuan.$q$),
(md5('neg-q-2')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Siswa meminta izin memakai aula dan mengusulkan waktu setelah pelajaran. Wakil sekolah menjawab, “Jika selesai sebelum pukul empat, kami setuju.” Fungsi jawaban itu adalah…$q$, $q$["Orientasi","Pengajuan awal","Penutup tanpa keputusan","Persetujuan bersyarat"]$q$::jsonb, 3, $q$Pihak sekolah menerima usulan dengan syarat waktu yang spesifik.$q$),
(md5('neg-q-3')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Pembeli berkata, “Harga itu terlalu mahal! Turunkan sekarang!” Penjual menjadi defensif. Penyebab yang paling masuk akal ialah…$q$, $q$["Pembeli menggunakan data terlalu kuat","Penjual salah memahami salam","Pembeli sudah mencapai kompromi","Nada memaksa menghambat dialog dan tidak memberi alasan"]$q$::jsonb, 3, $q$Nada memaksa dapat membuat lawan bicara defensif; alasan dan alternatif lebih produktif.$q$),
(md5('neg-q-4')::uuid, null, $q$Negosiasi: Kompromi$q$, $q$Dua kelompok ingin memakai laboratorium pada jam yang sama. Kelompok A butuh praktik wajib, B ingin merekam video tugas. Solusi paling seimbang ialah…$q$, $q$["Kelompok A memakai ruang sepanjang hari","Membagi waktu berdasarkan kebutuhan dan menyepakati jadwal tertulis","Kelompok B membatalkan tugas","Kelompok yang datang duluan otomatis menang"]$q$::jsonb, 1, $q$Jadwal bersama mempertimbangkan kebutuhan penting kedua pihak.$q$),
(md5('neg-q-5')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$Bandingkan: (1) “Pokoknya harga harus turun!” (2) “Apakah ada potongan jika kami membeli sepuluh unit?” Kalimat kedua lebih efektif karena…$q$, $q$["Santun, terbuka, dan memiliki alasan kuantitas","Mengandung ancaman tersirat","Tidak memberi ruang menjawab","Menutup negosiasi"]$q$::jsonb, 0, $q$Kalimat kedua meminta informasi dengan santun dan memberi dasar untuk menilai potongan.$q$),
(md5('neg-q-6')::uuid, null, $q$Negosiasi: Argumen$q$, $q$Siswa meminta tambahan tempat sampah karena sekolah terlihat kotor. Bukti tambahan yang paling memperkuat pengajuan adalah…$q$, $q$["Klaim bahwa semua sekolah lain punya banyak tempat sampah","Foto titik penumpukan sampah dan data jumlah siswa per area","Ancaman akan mengeluh","Mengulang permintaan dengan suara keras"]$q$::jsonb, 1, $q$Bukti yang dapat diamati dan terkait kebutuhan membuat argumen lebih terukur.$q$),
(md5('neg-q-7')::uuid, null, $q$Negosiasi: Kompromi$q$, $q$Vendor menawarkan paket Rp1.200.000, sedangkan anggaran Rp1.000.000. Vendor dapat mengurangi dekorasi Rp100.000; sekolah bisa menambah Rp100.000 jika transportasi termasuk. Analisis terbaik…$q$, $q$["Kesepakatan mustahil karena harga awal berbeda","Kompromi mungkin jika pengurangan dan layanan dirinci","Sekolah harus menerima harga awal","Vendor harus menanggung semua biaya"]$q$::jsonb, 1, $q$Kedua pihak mengubah unsur tawaran sehingga kesenjangan dapat diatasi dengan syarat jelas.$q$),
(md5('neg-q-8')::uuid, null, $q$Negosiasi: Etika$q$, $q$Seorang siswa berkata, “Kalau kamu tidak setuju, berarti kamu tidak peduli nilai kita.” Dampak utama kalimat itu adalah…$q$, $q$["Memperjelas data objektif","Menggunakan tekanan emosional yang dapat merusak kepercayaan","Menyusun persetujuan tertulis","Mendorong kompromi setara"]$q$::jsonb, 1, $q$Kalimat menyerang karakter dan menekan emosi, bukan membahas alasan.$q$),
(md5('neg-q-9')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Urutkan bagian berikut: (a) pembeli menyebut anggaran; (b) penjual menyapa; (c) harga disepakati; (d) penjual memberi alternatif harga; (e) kedua pihak berpamitan.$q$, $q$["a–c–b–d–e","d–b–a–e–c","b–a–d–c–e","b–d–e–a–c"]$q$::jsonb, 2, $q$Urutan logis: orientasi, pengajuan, penawaran, persetujuan, penutup.$q$),
(md5('neg-q-10')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$Kalimat “Kami bisa membayar Rp800.000 apabila pengiriman sudah termasuk” menunjukkan…$q$, $q$["Ancaman dan hukuman","Syarat yang menghubungkan harga dengan layanan","Penolakan mutlak tanpa alternatif","Salam pembuka"]$q$::jsonb, 1, $q$Kata “apabila” menghubungkan tawaran dengan syarat layanan.$q$),
(md5('neg-q-11')::uuid, null, $q$Negosiasi: Analisis kasus$q$, $q$Katering menawarkan 100 kotak Rp18.000 per kotak. Anggaran panitia Rp16.000 dan panitia butuh menu sehat. Respons paling kuat adalah…$q$, $q$["“Harga Anda tidak masuk akal.”","“Bisakah Rp16.000 dengan menu sederhana bergizi, atau ada paket lain sesuai anggaran?”","“Kami batal tanpa membahas pilihan.”","“Kami membayar berapa pun.”"]$q$::jsonb, 1, $q$Respons menyebut batas anggaran, mempertahankan kepentingan, dan membuka alternatif.$q$),
(md5('neg-q-12')::uuid, null, $q$Negosiasi: Argumen$q$, $q$Sekolah menolak bazar karena “kegiatan seperti ini selalu berantakan”, tanpa bukti. Kelemahan argumennya adalah…$q$, $q$["Generalisasi tanpa bukti khusus untuk rencana ini","Memiliki data terukur","Memuat syarat yang dapat diuji","Mengakui kepentingan siswa"]$q$::jsonb, 0, $q$Kata “selalu” merupakan generalisasi jika tidak disertai bukti relevan.$q$),
(md5('neg-q-13')::uuid, null, $q$Negosiasi: Kompromi$q$, $q$Satu kelompok ingin tema teknologi, kelompok lain ingin lingkungan. Mereka memilih “teknologi ramah lingkungan”. Keputusan ini…$q$, $q$["Menghindari semua kepentingan","Memastikan satu pihak kalah total","Menggabungkan unsur utama kedua usulan","Mengakhiri diskusi tanpa keputusan"]$q$::jsonb, 2, $q$Tema gabungan memadukan kepentingan teknologi dan lingkungan.$q$),
(md5('neg-q-14')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Saat pelanggan menolak harga, penjual langsung memberi diskon besar tanpa bertanya alasannya. Risikonya…$q$, $q$["Penjual memberi konsesi yang tak perlu karena belum memahami keberatan","Kebutuhan pelanggan pasti diketahui","Kesepakatan otomatis tertulis","Pelanggan tak mungkin menawar lagi"]$q$::jsonb, 0, $q$Klarifikasi keberatan sebaiknya dilakukan sebelum memberikan konsesi.$q$),
(md5('neg-q-15')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$“Saya memahami anggaran Anda terbatas. Bagaimana jika jumlah cetakan dikurangi?” Fungsi bagian pertama adalah…$q$, $q$["Menolak lawan bicara","Menunjukkan empati dan mengakui kendala pihak lain","Mengancam pembeli","Menyatakan persetujuan final"]$q$::jsonb, 1, $q$Pengakuan kendala pihak lain dapat membangun suasana kolaboratif.$q$),
(md5('neg-q-16')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$OSIS ingin konser sampai 21.00, sedangkan sekolah mengutamakan ketertiban dan transportasi siswa. Solusi seimbang adalah…$q$, $q$["Menetapkan waktu selesai, keamanan, dan rencana kepulangan","Konser tanpa batas waktu","Menolak tanpa mendengar alasan","Membiarkan semua pulang sendiri"]$q$::jsonb, 0, $q$Solusi mempertimbangkan acara, ketertiban, dan kepulangan siswa.$q$),
(md5('neg-q-17')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Harga sudah disepakati, tetapi kedua pihak masih membahas cara pembayaran. Analisis yang tepat adalah…$q$, $q$["Kesepakatan belum lengkap karena aspek penting lain belum disetujui","Negosiasi otomatis selesai saat harga disepakati","Dialog harus langsung ditutup","Cara pembayaran bukan bagian kesepakatan"]$q$::jsonb, 0, $q$Kesepakatan perlu mencakup rincian penting seperti cara pembayaran.$q$),
(md5('neg-q-18')::uuid, null, $q$Negosiasi: Argumen$q$, $q$Siswa mengusulkan konsultasi tambahan karena banyak siswa praktik saat jadwal biasa. Data itu relevan karena…$q$, $q$["Membuktikan guru tidak bekerja","Memaksa guru menerima semua usulan","Menjelaskan ketidakcocokan jadwal dengan kebutuhan siswa","Menggantikan diskusi"]$q$::jsonb, 2, $q$Data mendukung hubungan antara jadwal saat ini dan kebutuhan konsultasi.$q$),
(md5('neg-q-19')::uuid, null, $q$Negosiasi: Etika$q$, $q$Pembeli mengancam mempermalukan penjual jika harga tidak turun. Dibanding dialog santun, tindakan itu…$q$, $q$["Meningkatkan rasa percaya","Menjamin kesepakatan adil","Menjadi tekanan yang berpotensi merusak hubungan","Memperjelas rincian barang"]$q$::jsonb, 2, $q$Ancaman bukan alasan konstruktif dan dapat merusak kepercayaan.$q$),
(md5('neg-q-20')::uuid, null, $q$Negosiasi: Analisis dialog$q$, $q$Pembeli bertanya apakah garansi setahun termasuk. Penjual menjawab belum, tetapi bisa ditambahkan dengan biaya tertentu. Ini merupakan…$q$, $q$["Penutup final","Penawaran alternatif terkait syarat transaksi","Orientasi","Penolakan tanpa penjelasan"]$q$::jsonb, 1, $q$Penjual menawarkan pilihan tambahan beserta konsekuensi biaya.$q$),
(md5('neg-q-21')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Pembagian tugas sudah jelas, tetapi kelompok tidak menetapkan tenggat. Kelemahannya…$q$, $q$["Pembagian peran terlalu jelas","Kesepakatan terlalu rinci","Pelaksanaan sulit dipantau tanpa batas waktu","Kepentingan pasti bertentangan"]$q$::jsonb, 2, $q$Tenggat membantu memastikan kesepakatan dilaksanakan dan dievaluasi.$q$),
(md5('neg-q-22')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Pembeli bertanya, “Apa yang bisa disesuaikan agar sesuai anggaran kami?” Pertanyaan ini efektif karena…$q$, $q$["Menutup semua pilihan","Menyatakan ancaman","Mengundang pencarian opsi tanpa menyalahkan","Menghapus kebutuhan pembeli"]$q$::jsonb, 2, $q$Pertanyaan terbuka mendorong pemecahan masalah bersama.$q$),
(md5('neg-q-23')::uuid, null, $q$Negosiasi: Analisis kepentingan$q$, $q$Pengelola aula khawatir kursi tambahan menutup jalur evakuasi. Kepentingan utama yang perlu dipertimbangkan adalah…$q$, $q$["Mengurangi peserta sebagai satu-satunya tujuan","Membuat siswa kecewa","Menghindari semua perubahan","Keselamatan dan akses jalur evakuasi"]$q$::jsonb, 3, $q$Kekhawatiran pengelola berkaitan dengan keselamatan dan akses evakuasi.$q$),
(md5('neg-q-24')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$“Barang yang diterima berbeda dari pesanan; mari kita cocokkan catatannya” lebih konstruktif daripada “Anda menipu saya” karena…$q$, $q$["Menghindari fakta","Mengakhiri percakapan","Mengancam reputasi lawan","Menyebut masalah spesifik dan mengajak memeriksa bukti"]$q$::jsonb, 3, $q$Fokus pada ketidaksesuaian yang dapat diverifikasi membuka ruang penyelesaian.$q$),
(md5('neg-q-25')::uuid, null, $q$Negosiasi: Struktur$q$, $q$“Saya mengirim revisi kontrak hari ini dan Anda membayar setelah memeriksa.” Fungsi utama bagian ini adalah…$q$, $q$["Memperkenalkan pihak baru","Mengajukan konflik awal","Menyampaikan salam pembuka","Merangkum tindakan yang disepakati"]$q$::jsonb, 3, $q$Pernyataan memperjelas tindakan lanjutan yang disepakati.$q$),
(md5('neg-q-26')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Panitia ingin mencetak 500 brosur, sekolah ingin mengurangi kertas. Pilihan paling beralasan adalah…$q$, $q$["Menghitung kebutuhan dan menyediakan versi digital untuk sisanya","Mencetak sebanyak mungkin tanpa menghitung kebutuhan","Mengganti semua informasi dengan rumor","Membatalkan sosialisasi"]$q$::jsonb, 0, $q$Menghitung kebutuhan dan memakai versi digital dapat mengurangi kertas tanpa menghilangkan informasi.$q$),
(md5('neg-q-27')::uuid, null, $q$Negosiasi: Argumen$q$, $q$Penjual berkata, “Produk ini paling bagus karena saya yang menjualnya.” Mengapa argumen ini lemah?$q$, $q$["Menyertakan uji independen","Membandingkan spesifikasi objektif","Menawarkan garansi tertulis","Bersandar pada klaim sepihak tanpa bukti kualitas"]$q$::jsonb, 3, $q$Klaim penjual sendiri tidak cukup membuktikan mutu produk.$q$),
(md5('neg-q-28')::uuid, null, $q$Negosiasi: Kompromi$q$, $q$Sekolah hanya mengizinkan musik sampai 17.00. Panitia menerima batas itu dengan syarat persiapan dimulai lebih awal. Ini menunjukkan…$q$, $q$["Konsesi disertai penyesuaian untuk menjaga tujuan acara","Kegagalan total","Penolakan tanpa dialog","Persetujuan yang tidak terkait masalah"]$q$::jsonb, 0, $q$Panitia menerima waktu akhir dan menyesuaikan persiapan agar tujuan tetap tercapai.$q$),
(md5('neg-q-29')::uuid, null, $q$Negosiasi: Etika$q$, $q$Negosiator merangkum pendapat temannya sebelum menanggapi. Manfaat utamanya…$q$, $q$["Mempercepat konflik","Membuktikan teman salah","Menghindari semua argumen","Memastikan pemahaman dan menunjukkan bahwa pendapat didengar"]$q$::jsonb, 3, $q$Merangkum membantu klarifikasi dan mengurangi salah paham.$q$),
(md5('neg-q-30')::uuid, null, $q$Negosiasi: Analisis dialog$q$, $q$Pelanggan mengeluh barang terlambat. Penjual meminta maaf lalu menawarkan pengiriman besok pagi atau pengembalian ongkir. Ini menunjukkan…$q$, $q$["Pengakuan masalah dan pilihan pemulihan","Penolakan bertanggung jawab","Ancaman balik","Persetujuan harga tanpa solusi"]$q$::jsonb, 0, $q$Penjual mengakui masalah dan menawarkan dua pilihan penyelesaian.$q$),
(md5('neg-q-31')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Kesepakatan menyebut barang dikirim “secepatnya”. Mengapa rumusan ini perlu diperbaiki?$q$, $q$["Tidak memiliki waktu pasti dan bisa ditafsirkan berbeda","Terlalu spesifik","Memuat tanggung jawab","Mencantumkan tanggal keliru"]$q$::jsonb, 0, $q$Tanggal atau rentang waktu konkret mengurangi ambiguitas.$q$),
(md5('neg-q-32')::uuid, null, $q$Negosiasi: Analisis kepentingan$q$, $q$Penyewa ingin biaya rendah, pemilik gedung ingin mengurangi risiko kerusakan. Kesepakatan yang menjembatani keduanya adalah…$q$, $q$["Biaya wajar dengan deposit yang dikembalikan jika kondisi sesuai","Biaya rendah tanpa aturan penggunaan","Pemilik menanggung semua kerusakan","Penyewa dilarang memakai gedung"]$q$::jsonb, 0, $q$Deposit dan aturan kondisi melindungi pemilik serta memberi peluang biaya wajar.$q$),
(md5('neg-q-33')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Saat lawan bicara menyampaikan keberatan, respons terbaik sebelum mengajukan tawaran baru adalah…$q$, $q$["Mengklarifikasi alasan keberatan","Memotong pembicaraan","Mengulang tuntutan dengan nada tinggi","Langsung mengakhiri hubungan"]$q$::jsonb, 0, $q$Klarifikasi membantu memahami kepentingan sebelum merancang tawaran relevan.$q$),
(md5('neg-q-34')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$“Jika jadwal digeser ke Jumat, kami dapat menyediakan dua relawan tambahan” berfungsi sebagai…$q$, $q$["Ancaman","Tawaran bersyarat yang mengaitkan perubahan dengan kontribusi","Salam pembuka","Penolakan mutlak"]$q$::jsonb, 1, $q$Kata “jika” menandai syarat; tambahan relawan merupakan kontribusi.$q$),
(md5('neg-q-35')::uuid, null, $q$Negosiasi: Analisis argumen$q$, $q$Penyedia A lebih murah tetapi biaya kirim tidak jelas. B sedikit lebih mahal dengan pengiriman dan garansi tertulis. Perbandingan adil dilakukan dengan…$q$, $q$["Memilih A hanya dari harga awal","Memilih B karena harga lebih tinggi","Membandingkan total biaya, garansi, dan kebutuhan layanan","Mengabaikan syarat kontrak"]$q$::jsonb, 2, $q$Perbandingan perlu menggunakan komponen biaya dan layanan yang setara.$q$),
(md5('neg-q-36')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Setelah salam dan sebelum pihak lain menjawab, seseorang berkata, “Bolehkah saya mengusulkan jadwal pengganti?” Ini adalah…$q$, $q$["Persetujuan final","Penutup","Pengajuan","Evaluasi setelah kegiatan"]$q$::jsonb, 2, $q$Pembicara menyampaikan usulan sehingga termasuk pengajuan.$q$),
(md5('neg-q-37')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Kelompok A ingin rapat tatap muka, kelompok B terkendala transportasi. Alternatif paling inklusif adalah…$q$, $q$["Mewajibkan semua hadir tanpa pengecualian","Mengadakan rapat daring atau hibrida dengan waktu disepakati","Membatalkan tugas","Membiarkan kelompok B tidak mendapat informasi"]$q$::jsonb, 1, $q$Format daring atau hibrida mempertimbangkan kendala akses dan kebutuhan kolaborasi.$q$),
(md5('neg-q-38')::uuid, null, $q$Negosiasi: Etika$q$, $q$Negosiator menyembunyikan biaya tambahan hingga lawan menyetujui harga. Analisis etis yang tepat…$q$, $q$["Transparansi membangun kepercayaan","Kompromi terbaik","Semua pihak otomatis setara","Informasi penting ditahan sehingga persetujuan tidak didasarkan pemahaman utuh"]$q$::jsonb, 3, $q$Biaya tambahan adalah informasi material yang harus dijelaskan sebelum persetujuan.$q$),
(md5('neg-q-39')::uuid, null, $q$Negosiasi: Analisis dialog$q$, $q$“Kami belum dapat menyetujui Senin karena ruang dipakai ujian. Kami bisa hari Selasa atau Rabu.” Pernyataan itu menunjukkan…$q$, $q$["Penolakan mutlak tanpa solusi","Ancaman kepada pihak lain","Penolakan disertai alasan dan alternatif","Persetujuan tanpa syarat"]$q$::jsonb, 2, $q$Alasan jelas disertai alternatif menjaga negosiasi tetap terbuka.$q$),
(md5('neg-q-40')::uuid, null, $q$Negosiasi: Kompromi$q$, $q$Harga awal Rp2.000.000. Pembeli sanggup Rp1.700.000; penjual bisa menerima Rp1.800.000 jika pembayaran tepat waktu. Analisis terbaik…$q$, $q$["Kesenjangan tidak dapat dinegosiasikan","Pembeli harus menerima harga awal","Tawaran bersyarat Rp1.800.000 layak dinilai jika syarat jelas","Penjual wajib mengurangi harga tanpa syarat"]$q$::jsonb, 2, $q$Tawaran berada di antara posisi awal dan memiliki syarat yang dapat dinilai.$q$),
(md5('neg-q-41')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$“Data peminjaman menunjukkan 30 siswa belum mendapat buku; kami mengusulkan penambahan stok.” Lebih kuat daripada “Buku selalu kurang” karena…$q$, $q$["Menghindari alasan","Mengandung ancaman","Menggunakan data spesifik yang mendukung usulan","Menutup negosiasi"]$q$::jsonb, 2, $q$Angka spesifik mendukung kebutuhan lebih baik daripada klaim umum.$q$),
(md5('neg-q-42')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Dua pihak sepakat bekerja sama tetapi tidak membahas tanggung jawab jika terlambat. Yang perlu ditambahkan…$q$, $q$["Salam tambahan saja","Pujian kedua pihak","Penghapusan seluruh tenggat","Pembagian tanggung jawab, prosedur pemberitahuan, dan penanganan keterlambatan"]$q$::jsonb, 3, $q$Tanggung jawab dan prosedur mengurangi ketidakjelasan saat masalah muncul.$q$),
(md5('neg-q-43')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Negosiator menetapkan target, batas minimum, dan alternatif sebelum pertemuan. Manfaatnya…$q$, $q$["Tidak perlu mendengarkan pihak lain","Membantu keputusan realistis tanpa kehilangan arah","Menjamin pihak lain setuju","Menggantikan semua bukti"]$q$::jsonb, 1, $q$Persiapan membantu menentukan batas dan opsi, sambil tetap mendengar pihak lain.$q$),
(md5('neg-q-44')::uuid, null, $q$Negosiasi: Analisis kepentingan$q$, $q$Warga keberatan karena pembangunan bising malam hari; kontraktor ingin mengejar tenggat. Solusi tepat…$q$, $q$["Tetap bekerja malam tanpa pemberitahuan","Meminta warga menerima semua risiko","Mengatur pekerjaan bising siang hari dan menyesuaikan tahapan proyek","Menghentikan proyek tanpa diskusi"]$q$::jsonb, 2, $q$Penjadwalan mengurangi gangguan sekaligus menjaga perencanaan proyek.$q$),
(md5('neg-q-45')::uuid, null, $q$Negosiasi: Struktur$q$, $q$Dialog berisi salam, permintaan diskon, tawaran potongan dengan syarat pembelian banyak, persetujuan, dan terima kasih. Bagian penawaran adalah…$q$, $q$["Tawaran potongan bersyarat","Salam","Permintaan diskon saja","Ucapan terima kasih"]$q$::jsonb, 0, $q$Tawaran potongan merupakan alternatif dari pihak penjual.$q$),
(md5('neg-q-46')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Siswa meminta perpanjangan tenggat karena listrik padam. Guru ingin menjaga keadilan kelas. Respons tepat…$q$, $q$["Menolak semua alasan tanpa memeriksa","Memberi nilai nol langsung","Meminta penjelasan wajar dan menetapkan tenggat pengganti konsisten","Mengubah tenggat seluruh semester"]$q$::jsonb, 2, $q$Pemeriksaan wajar dan aturan pengganti menjaga empati serta keadilan.$q$),
(md5('neg-q-47')::uuid, null, $q$Negosiasi: Argumen$q$, $q$Seseorang berkata, “Semua teman setuju, jadi usulan ini pasti benar.” Kelemahan penalaran itu…$q$, $q$["Menyajikan data pengujian","Menganggap popularitas sebagai bukti tanpa menilai alasan","Mengakui keterbatasan data","Membandingkan alternatif"]$q$::jsonb, 1, $q$Banyak orang setuju tidak otomatis membuktikan usulan paling tepat.$q$),
(md5('neg-q-48')::uuid, null, $q$Negosiasi: Kebahasaan$q$, $q$“Saya menghargai tawaran itu, tetapi biayanya melampaui anggaran. Adakah paket dengan fitur inti saja?” Ini menunjukkan…$q$, $q$["Persetujuan penuh","Ancaman dan ultimatum","Penutup tanpa tindak lanjut","Penolakan santun disertai permintaan alternatif"]$q$::jsonb, 3, $q$Pembicara menghargai tawaran, menjelaskan kendala, dan meminta opsi lain.$q$),
(md5('neg-q-49')::uuid, null, $q$Negosiasi: Evaluasi$q$, $q$Satu pihak memahami “dua kali revisi” sebagai dua putaran, pihak lain sebagai dua perubahan kecil. Pencegahan terbaik…$q$, $q$["Membiarkan tafsir berbeda","Mengandalkan ingatan","Membatalkan komunikasi","Menuliskan definisi revisi, jumlah putaran, dan batas perubahan"]$q$::jsonb, 3, $q$Definisi tertulis mengurangi ambiguitas.$q$),
(md5('neg-q-50')::uuid, null, $q$Negosiasi: Strategi$q$, $q$Negosiator menemui jalan buntu. Pertanyaan yang paling berpotensi membuka pilihan baru adalah…$q$, $q$["“Siapa yang akan mengalah?”","“Mengapa Anda selalu sulit?”","“Kita hentikan sekarang.”","“Selain harga, apa yang bisa disesuaikan: jumlah, waktu kirim, atau layanan?”"]$q$::jsonb, 3, $q$Memperluas unsur yang dapat dinegosiasikan membantu menemukan opsi baru.$q$),
(md5('neg-q-51')::uuid, null, $q$Negosiasi: Sintesis kasus$q$, $q$Penyedia X murah tetapi bukti higienitas belum jelas. Y lebih mahal, memiliki bukti kelayakan, dan bersedia menyesuaikan menu. Keputusan bertanggung jawab adalah…$q$, $q$["Memverifikasi keamanan pangan dan menegosiasikan menu Y agar sesuai anggaran","Memilih X hanya karena murah","Memilih Y tanpa meninjau anggaran","Membatalkan konsumsi tanpa alternatif"]$q$::jsonb, 0, $q$Keamanan pangan perlu diverifikasi dan menu dapat disesuaikan dengan anggaran.$q$),
(md5('neg-q-52')::uuid, null, $q$Negosiasi: Sintesis kasus$q$, $q$Harga, kualitas, dan tanggal pengiriman telah disepakati. Sebelum mengakhiri negosiasi, tindakan paling penting adalah…$q$, $q$["Mengulang konflik awal","Merangkum ketentuan, memastikan pemahaman sama, dan menetapkan tindak lanjut tertulis","Menambah tuntutan baru tanpa alasan","Menganggap detail tidak penting"]$q$::jsonb, 1, $q$Rangkuman dan dokumentasi memastikan kesepakatan dipahami sama dan dapat dilaksanakan.$q$)
