-- =====================================================================
--  UH Hikayat — SOAL TAMBAHAN: Teks Negosiasi (52 soal HOTS C4)
--  Jalankan SETELAH migrasi_v3.sql (boleh sebelum/sesudah migrasi_v3_seed_soal_lama.sql).
--  Aman dijalankan ulang (on conflict do nothing). Soal lama tidak diubah.
--  Soal masuk ke BANK SOAL; ujiannya dibuat berstatus DRAF (kelas & jadwal diatur guru di aplikasi).
--  Posisi kunci jawaban sudah diacak merata (A/B/C/D masing-masing 13/13/13/13 soal).
-- =====================================================================
on conflict (id) do nothing;

values (md5('neg-exam')::uuid, 'UH Teks Negosiasi (52 soal)', 'Bahasa Indonesia', 90, 'draf')
on conflict (id) do nothing;

select md5('neg-exam')::uuid, md5('neg-q-'||n)::uuid, n from generate_series(1,52) n
on conflict do nothing;
